// Logo oficial de SINSA optimizado en Base64 para inserción nativa en documentos Word y previsualización
const SINSA_LOGO_BASE64 = "";

// Mapa satelital certificado de delimitacion territorial (Chinandega - BAJO CERO) en Base64 para Anexo III
const GEOCERCA_CHINANDEGA_MAP_BASE64 = "";
if (typeof window !== 'undefined') {
    window.GEOCERCA_CHINANDEGA_MAP_BASE64 = GEOCERCA_CHINANDEGA_MAP_BASE64;
    window.SINSA_LOGO_BASE64 = SINSA_LOGO_BASE64;
}
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { SINSA_LOGO_BASE64, GEOCERCA_CHINANDEGA_MAP_BASE64 };
}
